            &lt;div id="linkContainer"&gt;
                &lt;center&gt;
                    &lt;ul class="desktop" id="links"&gt;
                        &lt;li&gt;&lt;a class="headerLinks" href="/"&gt;Home Page&lt;/a&gt;&lt;/li&gt;
                        &lt;li&gt;&lt;a class="headerLinks" href="/names"&gt;All Names&lt;/a&gt;&lt;/li&gt;&lt;br class="mobile"&gt;
                        &lt;li&gt;&lt;a class="headerLinks" href="/faqs"&gt;FAQs&lt;/a&gt;&lt;/li&gt;
                        &lt;li&gt;&lt;a class="headerLinks" href="/about"&gt;About&lt;/a&gt;&lt;/li&gt;
                    &lt;/ul&gt;
                    &lt;ul class="mobile" id="links"&gt;
                        &lt;li id="first"&gt;
                            &lt;div&gt;
                                &lt;a id="first" class="headerLinks" href="/"&gt;Home Page&lt;/a&gt;
                                &lt;a class="headerLinks" href="/names"&gt;All Names&lt;/a&gt;
                            &lt;/div&gt;
                        &lt;/li&gt;
                        &lt;li&gt;
                            &lt;div&gt;
                                &lt;a id="first" class="headerLinks" href="/faqs"&gt;FAQs&lt;/a&gt;
